"""گزارش ماهانه‌ی آزمایشی شبیه خروجی PDF از Excel (داده‌ها ساختگی‌اند).

ویژگی‌های واقعی این PDFها: سربرگ تکراری در هر صفحه، سلول‌ها به ترتیب نامنظم در متن، «لا» به «ال» شکسته
(«خالصه»، «مشکالت»)، رقم و حرف چسبیده («شهریور ماه1405»)، و بخش‌های مهم در صفحه‌های آخر.
"""
import io

import pymupdf

from tests.fixtures.automation_letter import CSS, FONT_DIR, _html

HEAD = """گزارش ماهیانه منتهی به
1405
شماره قرارداد:شماره صفحه
1403-118
{page}
احداث راه دسترسی نمونه و
تاسیسات جانبی میدان آزمایشی
شماره گزارش:
ABC-XY-MR-007
مهر ماه"""

PAGES = {
    1: "گزارش ماهیانه پیشرفت کار",
    2: "فهرست\nخالصه اقدامات انجام شده\nلیست مشکالت و موانع\nپیش بینی فعالیت ماه آتی\nماشین آالت",
    3: "مشخصات پروژه\nتاریخ شروع به کار1404/05/01\nمدت اولیه پیمان :\n16\nماه(شمسی)",
    5: "ردیف\nشرح اقدامات\n1\nانجام اقدامات مربوط به تجهیز کارگاه\n2\nاجرای عملیات خاکریزی از کیلومتر000\n+\n0\nالی000\n+\n12\n"
       "3\nبرگزاری کالس ایمنی برای پرسنل کارگاه\nخالصه اقدامات انجام شده در ماه",
    8: "جدول نیروی انسانی\n1 مدیر پروژه 30\n1\n2 کارگر ساده 1900\n63\n572\n19\n2400\n80 جمع نفرات ماه",
    14: "ردیف\n1\n2\nتاخیر در تحویل زمین بازه دوم از طرف کارفرما\nکمبود ماشین آالت سنگین در کارگاه\nتوضیحات\nلیست مشکالت و موانع\nشرح مشکل(پیمانکار)",
    15: "شرح فعالیت\nردیف\nبرنامه زمانی\nاجرای عملیات ابنیه کالورتهای بازه2ادامه\nاجرای عملیات زیراساس بازه1جدید\n"
        "پیش بینی فعالیت ماه آتی",
}


def build(pages: int = 16) -> bytes:
    doc = pymupdf.open()
    for no in range(1, pages + 1):
        page = doc.new_page()
        text = HEAD.format(page=no) + "\n" + PAGES.get(no, f"جدول شماره {no}\n12.5%\n87.5%\n100.00%")
        page.insert_htmlbox(pymupdf.Rect(30, 30, 565, 810), _html(text), css=CSS, archive=pymupdf.Archive(FONT_DIR))
    doc.set_metadata({"creator": "Microsoft® Excel® 2024", "producer": "Microsoft® Excel® 2024"})
    buf = io.BytesIO()
    doc.save(buf)
    return buf.getvalue()
